// Binary search by champion name
inline const ChampionEntry* FindChampion(const char* name) {
    int lo = 0, hi = kChampionCount - 1;
    while (lo <= hi) {
        const int mid = (lo + hi) / 2;
        const int cmp = strcmp(name, kChampions[mid].Name);
        if (cmp == 0) return &kChampions[mid];
        if (cmp < 0) hi = mid - 1;
        else lo = mid + 1;
    }
    return nullptr;
}

